"""Load one point-based crop dataset from its HDF5 file."""

# Import path handling and HDF5 access for the crop point files.
from pathlib import Path

import h5py
import numpy as np


# Limit crop names to the three datasets generated by the converter.
VALID_CROPS = {"wheat", "maize", "rice"}
# Resolve the default crop folder from this module so loading is independent of the working directory.
DEFAULT_CROP_DIRECTORY = Path(__file__).resolve().parent.parent / "data" / "processed" / "crop"


def load_data(crop_name: str, data_directory: Path = DEFAULT_CROP_DIRECTORY) -> dict[str, np.ndarray | float]:
    """Load crop coordinates, MATLAB-style indices, extents, and grid metadata.

    Latitude, longitude, and time values are returned as aligned one-dimensional
    arrays. ``index`` is an ``(N, 3)`` integer matrix with one-based regional
    latitude, longitude, and time indices. Extents and coordinates use degrees.
    """
    # Normalize and validate the requested crop name before opening the file.
    crop_name = crop_name.lower()
    if crop_name not in VALID_CROPS:
        raise ValueError(f"crop_name must be one of {sorted(VALID_CROPS)}")
    # Resolve relative custom folders from the current working directory and report a missing file clearly.
    path = Path(data_directory) / f"{crop_name}.h5"
    if not path.exists():
        raise FileNotFoundError(f"No crop file exists: {path}")
    # Read point arrays and regional metadata from the converted crop object.
    with h5py.File(path, "r") as source:
        required_datasets = {
            "lat", "lon", "time", "index", "lat_extent", "lon_extent", "padding",
            "delta", "time_step", "start_time", "end_time",
        }
        missing_datasets = required_datasets.difference(source.keys())
        if missing_datasets:
            # Make old full-grid or incomplete files fail with a descriptive message.
            raise ValueError(
                f"Crop file {path} is not in point format; missing datasets: {sorted(missing_datasets)}"
            )
        result = {
            "lat": source["lat"][:],
            "lon": source["lon"][:],
            "time": source["time"][:],
            "index": source["index"][:].astype(np.int64),
            "lat_extent": source["lat_extent"][:],
            "lon_extent": source["lon_extent"][:],
            "padding": float(source["padding"][()]),
            "delta": float(source["delta"][()]),
            "time_step": float(source["time_step"][()]),
            "start_time": float(source["start_time"][()]),
            "end_time": float(source["end_time"][()]),
        }
    # Confirm that every point coordinate has exactly one three-axis index row.
    point_count = result["lat"].size
    if result["lon"].size != point_count or result["time"].size != point_count:
        raise ValueError(f"Crop file {path} has misaligned coordinate and time arrays.")
    if result["index"].shape != (point_count, 3):
        raise ValueError(f"Crop file {path} must contain an (N, 3) index matrix.")
    # Return the stored crop point object without rebuilding or saving regional grid axes.
    return result


if __name__ == "__main__":
    # Demonstrate loading the default wheat point dataset and its core fields.
    result = load_data("wheat")
    print(result["lat"].shape, result["index"].shape, result["lat_extent"], result["lon_extent"])
